import { useState, useMemo, useEffect, useCallback } from "react";
import {
  Calendar,
  Clock,
  Users,
  ChevronLeft,
  ChevronRight,
  CalendarDays,
} from "lucide-react";
import { formatDateToLocalString, formatTime } from "@/lib/dateUtils";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { StandardPage } from "@/components/common";
import { useBookingLogic } from "@/hooks/client/Booking/useBookingLogic";
import { useAuth } from "@/features/auth";

const DAYS_SHORT = ["Dom", "Lun", "Mar", "Mié", "Jue", "Vie", "Sáb"];

const getWeekDates = (startDate: Date) => {
  const dates = [];
  const current = new Date(startDate);

  // Find the start of the week (Monday)
  const dayOfWeek = current.getDay();
  const mondayOffset = dayOfWeek === 0 ? -6 : 1 - dayOfWeek;
  current.setDate(current.getDate() + mondayOffset);

  for (let i = 0; i < 7; i++) {
    dates.push(new Date(current));
    current.setDate(current.getDate() + 1);
  }
  return dates;
};

export function BookingPage() {
  const { user } = useAuth();
  const {
    timeSlots,
    userBookings,
    userProfile,
    isLoading,
    isBooking,
    createBooking,
    fetchAvailability,
    getAvailability,
    refresh,
  } = useBookingLogic(user?.id);

  const [selectedDate, setSelectedDate] = useState<Date>(new Date());
  const [viewWeek, setViewWeek] = useState<Date>(new Date());

  const formatDate = useCallback((date: Date) => {
    return formatDateToLocalString(date);
  }, []);

  const weekDates = useMemo(() => getWeekDates(viewWeek), [viewWeek]);

  const goToPreviousWeek = () => {
    const newWeek = new Date(viewWeek);
    newWeek.setDate(newWeek.getDate() - 7);
    setViewWeek(newWeek);
  };

  const goToNextWeek = () => {
    const newWeek = new Date(viewWeek);
    newWeek.setDate(newWeek.getDate() + 7);
    setViewWeek(newWeek);
  };

  const goToToday = () => {
    const today = new Date();
    setViewWeek(today);
    setSelectedDate(today);
  };

  const handleBooking = async (timeSlotId: string, bookingDate: string) => {
    const booking = await createBooking(timeSlotId, bookingDate);
    if (booking) {
      await fetchAvailability(timeSlotId, bookingDate);
    }
  };

  const getSlotsForDate = useCallback(
    (date: Date) => {
      const dateString = formatDate(date);
      const dayOfWeek = date.getDay();

      return timeSlots.filter((slot) => {
        if (slot.slot_type === "specific_date") {
          return slot.specific_date === dateString;
        }
        return slot.day_of_week === dayOfWeek;
      });
    },
    [timeSlots, formatDate],
  );

  const isPastDate = (date: Date) => {
    const today = new Date();
    today.setHours(0, 0, 0, 0);
    return date < today;
  };

  const isPastSlot = (date: Date, startTime: string) => {
    const today = new Date();
    const [hours, minutes] = startTime.split(":").map(Number);
    const slotDate = new Date(date);
    slotDate.setHours(hours, minutes, 0, 0);
    return slotDate < today;
  };

  const isToday = (date: Date) => {
    const today = new Date();
    return formatDate(date) === formatDate(today);
  };

  const isSelectedDate = (date: Date) => {
    return formatDate(date) === formatDate(selectedDate);
  };

  const hasAvailableSlots = (date: Date) => {
    const slots = getSlotsForDate(date);

    return slots.some((slot) => {
      const availability = getAvailability(slot.id, formatDate(date));
      return availability && availability.available > 0;
    });
  };

  const hasBookingOnDate = (date: Date) => {
    const dateStr = formatDate(date);
    return userBookings.some(
      (booking) =>
        booking.booking_date === dateStr &&
        (booking.status === "confirmed" || booking.status === "pending"),
    );
  };

  // Load availability for visible time slots when dates change
  useEffect(() => {
    const loadAvailability = async () => {
      for (const date of weekDates) {
        const slots = getSlotsForDate(date);

        for (const slot of slots) {
          await fetchAvailability(slot.id, formatDate(date));
        }
      }
    };

    if (timeSlots.length > 0) {
      loadAvailability();
    }
  }, [weekDates, timeSlots, formatDate, getSlotsForDate, fetchAvailability]);

  return (
    <StandardPage
      icon={CalendarDays}
      title="Reservar Clase"
      description={
        userProfile
          ? `${userProfile.credits ?? 0} créditos disponibles`
          : "Cargando créditos..."
      }
      onRefresh={refresh}
      isLoading={isLoading}
      loadingMessage="Cargando horarios disponibles..."
      actionButton={
        <Button onClick={goToToday} variant="outline" size="sm">
          <Calendar className="size-4 mr-1" />
          Hoy
        </Button>
      }
      maxWidth="max-w-4xl"
    >
      {timeSlots.length === 0 && !isLoading ? (
        <Card>
          <CardContent className="py-12 text-center">
            <CalendarDays className="size-12 mx-auto text-muted-foreground mb-4" />
            <h3 className="text-lg font-medium mb-2">
              No hay horarios disponibles
            </h3>
            <p className="text-muted-foreground">
              Los horarios aparecerán aquí cuando estén configurados
            </p>
          </CardContent>
        </Card>
      ) : (
        <>
          {/* Week Navigation */}
          {/* Week Navigation */}
          <Card>
            <CardHeader className="pb-2">
              <div className="flex items-center justify-between">
                <Button
                  onClick={goToPreviousWeek}
                  variant="ghost"
                  size="sm"
                  className="h-8 w-8 p-0"
                >
                  <ChevronLeft className="size-4" />
                </Button>
                <CardTitle className="text-center text-base">
                  {weekDates[0].toLocaleDateString("es-ES", {
                    month: "long",
                    year: "numeric",
                  })}
                </CardTitle>
                <Button
                  onClick={goToNextWeek}
                  variant="ghost"
                  size="sm"
                  className="h-8 w-8 p-0"
                >
                  <ChevronRight className="size-4" />
                </Button>
              </div>
            </CardHeader>
            <CardContent className="pt-2 px-2">
              <div className="grid grid-cols-7 gap-1">
                {weekDates.map((date, index) => {
                  const hasSlots = hasAvailableSlots(date);
                  const isTodayDate = isToday(date);
                  const isBooked = hasBookingOnDate(date);

                  return (
                    <button
                      key={index}
                      onClick={() => setSelectedDate(date)}
                      disabled={isPastDate(date)}
                      className={`p-1.5 text-center rounded-md border transition-colors relative h-16 flex flex-col justify-center ${
                        isPastDate(date)
                          ? "bg-muted text-muted-foreground cursor-not-allowed opacity-60"
                          : isSelectedDate(date)
                            ? "bg-primary text-primary-foreground border-primary shadow-sm"
                            : isBooked
                              ? "border-blue-400 bg-blue-50"
                              : isTodayDate
                                ? "border-primary bg-primary/5"
                                : "hover:bg-muted border-border"
                      }`}
                    >
                      <div
                        className={`text-[9px] leading-none mb-1 uppercase ${
                          isBooked && !isSelectedDate(date)
                            ? "text-blue-600 font-medium"
                            : isTodayDate && !isSelectedDate(date)
                              ? "text-primary font-medium"
                              : "text-muted-foreground"
                        }`}
                      >
                        {DAYS_SHORT[date.getDay()]}
                      </div>
                      <div className="text-sm font-bold leading-none">
                        {date.getDate()}
                      </div>
                      {hasSlots && !isPastDate(date) && (
                        <div className="absolute bottom-1 left-1/2 -translate-x-1/2">
                          <div
                            className={`w-1 h-1 rounded-full ${
                              isSelectedDate(date)
                                ? "bg-primary-foreground"
                                : "bg-green-500"
                            }`}
                          />
                        </div>
                      )}
                    </button>
                  );
                })}
              </div>
            </CardContent>
          </Card>

          {/* Available Slots for Selected Date */}
          <div className="space-y-2">
            <div className="flex items-center gap-2 px-1">
              <Clock className="size-4 text-muted-foreground" />
              <h2 className="font-semibold text-base">
                {selectedDate.toLocaleDateString("es-ES", {
                  weekday: "long",
                  day: "numeric",
                  month: "long",
                })}
              </h2>
            </div>

            {(() => {
              const daySlots = getSlotsForDate(selectedDate);

              if (daySlots.length === 0) {
                return (
                  <Card>
                    <CardContent className="py-8 text-center">
                      <Clock className="size-12 mx-auto text-muted-foreground mb-4" />
                      <p className="text-sm text-muted-foreground">
                        No hay horarios disponibles para este día
                      </p>
                    </CardContent>
                  </Card>
                );
              }

              return (
                <div className="space-y-2">
                  {daySlots
                    .sort((a, b) => a.start_time.localeCompare(b.start_time))
                    .map((slot) => {
                      const availability = getAvailability(
                        slot.id,
                        formatDate(selectedDate),
                      );
                      const isAvailable =
                        availability && availability.available > 0;
                      const userBooking = userBookings.find(
                        (b) =>
                          b.time_slot_id === slot.id &&
                          b.booking_date === formatDate(selectedDate) &&
                          (b.status === "confirmed" || b.status === "pending"),
                      );
                      const isBooked = !!userBooking;
                      const isSlotInPast = isPastSlot(selectedDate, slot.start_time);
                      const canBook =
                        !isPastDate(selectedDate) &&
                        !isSlotInPast &&
                        isAvailable &&
                        (userProfile?.credits ?? 0) > 0 &&
                        !isBooking &&
                        !isBooked;

                      return (
                        <div
                          key={slot.id}
                          className={`p-3 rounded-lg border ${
                            isSlotInPast
                              ? "border-gray-200 bg-gray-50 opacity-60"
                              : isBooked
                                ? "border-blue-200 bg-blue-50"
                                : isAvailable
                                  ? "border-green-200 bg-green-50"
                                  : "border-gray-200 bg-gray-50"
                          }`}
                        >
                          <div className="space-y-3">
                            <div className="flex items-center justify-between">
                              <div>
                                <div className="font-semibold text-base">
                                  {formatTime(slot.start_time)} -{" "}
                                  {formatTime(slot.end_time)}
                                </div>
                                <div className="flex items-center gap-1 text-xs text-muted-foreground">
                                  <Users className="size-3" />
                                  {availability ? (
                                    <span>
                                      {availability.available}/
                                      {availability.capacity} plazas
                                    </span>
                                  ) : (
                                    <span>Cargando...</span>
                                  )}
                                </div>
                              </div>
                              <Badge
                                variant={
                                  isBooked
                                    ? "default"
                                    : isAvailable
                                      ? "default"
                                      : "secondary"
                                }
                                className={`text-xs ${
                                  isBooked
                                    ? userBooking?.status === "pending"
                                      ? "bg-yellow-500 text-white"
                                      : "bg-blue-500 text-white"
                                    : isAvailable
                                      ? "bg-green-500 text-white"
                                      : ""
                                }`}
                              >
                                {isBooked
                                  ? userBooking?.status === "pending"
                                    ? "Pendiente"
                                    : "Reservado"
                                  : availability && availability.available > 0
                                    ? "Disponible"
                                    : "Completo"}
                              </Badge>
                            </div>

                            <Button
                              className="w-full h-9 text-sm"
                              disabled={!canBook || isSlotInPast}
                              onClick={() =>
                                handleBooking(slot.id, formatDate(selectedDate))
                              }
                            >
                              {isSlotInPast
                                ? "Horario pasado"
                                : isBooked
                                  ? userBooking?.status === "pending"
                                    ? "Pendiente de aprobación"
                                    : "Ya tienes reserva"
                                  : (userProfile?.credits ?? 0) <= 0
                                    ? "Sin créditos"
                                    : isBooking
                                      ? "Reservando..."
                                      : "Reservar (1 crédito)"}
                            </Button>
                          </div>
                        </div>
                      );
                    })}
                </div>
              );
            })()}
          </div>
        </>
      )}
    </StandardPage>
  );
}

/**
 * Tests de Reserva de Clases
 * Cubre: BOOK-01 a BOOK-04
 */

import { test, expect } from "../fixtures/auth.fixtures";
import {
  waitForLoadingComplete,
  navigateToClientSection,
} from "../helpers/test-helpers";

test.describe("Reserva de Clases - Cliente", () => {
  test.beforeEach(async ({ authenticatedClient: page }) => {
    await navigateToClientSection(page, "book");
  });

  test("BOOK-01: Ver calendario de clases", async ({
    authenticatedClient: page,
  }) => {
    await waitForLoadingComplete(page);

    // Verificar que estamos en la página de reservas - puede mostrar calendario o mensaje vacío
    // Si hay horarios: muestra días de la semana (Lun, Mar, etc.)
    // Si no hay horarios: muestra "No hay horarios disponibles"
    const calendar = page
      .locator("text=Lun")
      .or(page.locator("text=Mar"))
      .or(page.locator("text=Mié"));
    const emptyState = page
      .locator("text=No hay horarios disponibles")
      .or(page.locator("text=Reservar Clase"));

    const calendarVisible = await calendar
      .first()
      .isVisible()
      .catch(() => false);
    const emptyVisible = await emptyState
      .first()
      .isVisible()
      .catch(() => false);

    // Debe mostrar el calendario O el estado vacío
    expect(calendarVisible || emptyVisible).toBeTruthy();
  });

  test("BOOK-02: Navegar a la semana siguiente", async ({
    authenticatedClient: page,
  }) => {
    await waitForLoadingComplete(page);

    // Buscar botón de siguiente semana (normalmente un chevron o flecha)
    const nextWeekButton = page
      .locator('button:has-text("›")')
      .or(page.locator('button:has-text(">")'))
      .or(page.locator('button[aria-label*="siguiente"]'));

    if (
      await nextWeekButton
        .first()
        .isVisible()
        .catch(() => false)
    ) {
      await nextWeekButton.first().click();
      await page.waitForTimeout(1000);
    }

    // El calendario debería seguir visible
    await expect(page.locator("main")).toBeVisible();
  });

  test("BOOK-03: Navegar a la semana anterior", async ({
    authenticatedClient: page,
  }) => {
    await waitForLoadingComplete(page);

    // Primero ir a la siguiente semana
    const nextButton = page
      .locator('button:has-text("›")')
      .or(page.locator('button:has-text(">")'));
    if (
      await nextButton
        .first()
        .isVisible()
        .catch(() => false)
    ) {
      await nextButton.first().click();
      await page.waitForTimeout(500);
    }

    // Ahora ir a la semana anterior
    const prevWeekButton = page
      .locator('button:has-text("‹")')
      .or(page.locator('button:has-text("<")'));

    if (
      await prevWeekButton
        .first()
        .isVisible()
        .catch(() => false)
    ) {
      await prevWeekButton.first().click();
      await page.waitForTimeout(1000);
    }

    // El calendario debería seguir visible
    await expect(page.locator("main")).toBeVisible();
  });

  test("BOOK-04: Botón Hoy funciona", async ({ authenticatedClient: page }) => {
    await waitForLoadingComplete(page);

    // Buscar botón "Hoy"
    const todayButton = page.locator('button:has-text("Hoy")');

    if (await todayButton.isVisible().catch(() => false)) {
      await todayButton.click();
      await page.waitForTimeout(1000);
    }

    // Verificar que el calendario sigue visible
    await expect(page.locator("main")).toBeVisible();
  });

  test("BOOK-05: Ver slots disponibles al seleccionar un día", async ({
    authenticatedClient: page,
  }) => {
    await waitForLoadingComplete(page);

    // Click en un día del calendario - buscar botones con números (días)
    const dayButton = page
      .locator("button")
      .filter({ hasText: /^[0-9]{1,2}$/ })
      .first();

    if (await dayButton.isVisible().catch(() => false)) {
      await dayButton.click();
      await page.waitForTimeout(1500);
    }

    // Debería mostrar contenido
    await expect(page.locator("main")).toBeVisible();
  });

  test("BOOK-06: Slots muestran capacidad disponible", async ({
    authenticatedClient: page,
  }) => {
    await waitForLoadingComplete(page);

    // Verificar que la página carga correctamente
    await expect(page.locator("main")).toBeVisible();
  });

  test("BOOK-07: Reservar una clase (si hay créditos)", async ({
    authenticatedClient: page,
  }) => {
    await waitForLoadingComplete(page);

    // Buscar un slot disponible con botón de reservar
    const bookButton = page.locator('button:has-text("Reservar")');

    if (
      await bookButton
        .first()
        .isVisible()
        .catch(() => false)
    ) {
      // Verificar que el botón existe
      await expect(bookButton.first()).toBeVisible();
    }
    expect(true).toBeTruthy();
  });

  test("BOOK-08: Mensaje cuando no hay créditos suficientes", async ({
    authenticatedClient: page,
  }) => {
    await waitForLoadingComplete(page);

    // Verificar que la página carga correctamente
    await expect(page.locator("main")).toBeVisible();
  });

  test("BOOK-09: Slots pasados no son seleccionables", async ({
    authenticatedClient: page,
  }) => {
    await waitForLoadingComplete(page);

    // Buscar si hay botones indicando horarios pasados
    const pastSlotButtons = page.locator('button:has-text("Horario pasado")');

    if (await pastSlotButtons.first().isVisible().catch(() => false)) {
      const count = await pastSlotButtons.count();
      for (let i = 0; i < count; i++) {
        const button = pastSlotButtons.nth(i);
        await expect(button).toBeDisabled();
        await expect(button).toHaveText("Horario pasado");
      }
    }

    // Verificar que la página carga correctamente
    await expect(page.locator("main")).toBeVisible();
  });
});
